package migrations

import "gorm.io/gorm"

// migrateUserPasswordGenerated adds users.password_generated, which marks an
// account whose stored password was generated by the server (OIDC
// auto-provisioning) and was never known to the user. Existing rows default to
// false: their provenance is unknown, and false preserves today's behaviour.
// Fixed SQL keeps this migration independent of future model changes; a column
// that already exists (fresh databases created from the current model) is left
// alone.
func migrateUserPasswordGenerated(db *gorm.DB) error {
	if !db.Migrator().HasTable("users") || db.Migrator().HasColumn("users", "password_generated") {
		return nil
	}
	columnType := "numeric"
	if db.Dialector.Name() == "postgres" {
		columnType = "boolean"
	}
	return db.Exec("ALTER TABLE users ADD COLUMN password_generated " + columnType + " NOT NULL DEFAULT false").Error
}
